import { useState, lazy, Suspense } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../contexts/AuthContext'
import { useSidebar } from '@/contexts/SidebarContext'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Package, MapPin, Weight, Plus, X, Upload, FileText, ListTodo, Mountain, PanelLeft } from 'lucide-react'
import { getDisplayNameFromEmail } from '@/utils/user'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { useGearCount, useCreateGear, useBulkCreateGear } from '@/hooks/useGearData'
import { useListCount } from '@/hooks/useListData'
import { Skeleton } from '@/components/ui/skeleton'
import type { ParsedGearItem } from '@/utils/csvParser'

// Lazy load the heavy import component
const ImportGearForm = lazy(() => import('@/components/gear/ImportGearForm').then(m => ({ default: m.ImportGearForm })))

export function Dashboard() {
  const { user } = useAuth()
  const { toggleSidebar, isCollapsed: isSidebarCollapsed } = useSidebar()
  const navigate = useNavigate()
  const [showAddGear, setShowAddGear] = useState(false)
  const [showImport, setShowImport] = useState(false)

  // Get time-based greeting
  const getGreeting = () => {
    const hour = new Date().getHours()
    if (hour < 12) return 'Good morning'
    if (hour < 18) return 'Good afternoon'
    return 'Good evening'
  }

  // Use React Query hooks for data fetching and mutations
  const { data: gearCountData, isLoading: isLoadingCounts } = useGearCount(user?.id)
  const { data: listCount = 0, isLoading: isLoadingListCount } = useListCount(user?.id)
  const gearCount = gearCountData?.count || 0
  const categoryCount = gearCountData?.categories || 0
  const createGearMutation = useCreateGear(user?.id)
  const bulkCreateGearMutation = useBulkCreateGear(user?.id)

  const handleAddGear = async (gear: {
    name: string
    weight_grams: number
    category: string
    quantity: number
    worn: boolean
    consumable: boolean
    notes?: string | null
    price?: number | null
    description?: string | null

import { useState, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Package } from 'lucide-react'
import { useGearItems, useCreateGear, useUpdateGear, useDeleteGear } from '@/hooks/useGearData'
import { GearCard } from '@/components/gear/GearCard'
import { GearRow } from '@/components/gear/GearRow'
import { GearCompactRow } from '@/components/gear/GearCompactRow'
import { CollectionTable } from '@/components/shared/CollectionTable'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import { useViewMode } from '@/hooks/shared/useViewMode'
import { useWeightUnit } from '@/hooks/shared/useWeightUnit'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export function GearPage() {
  const { user } = useAuth()

  // Use React Query hooks for data fetching and mutations
  const { data: items = [], isLoading: loading } = useGearItems(user?.id)
  const createGearMutation = useCreateGear(user?.id)
  const updateGearMutation = useUpdateGear(user?.id)
  const deleteGearMutation = useDeleteGear(user?.id)

  const [viewMode, setViewMode] = useViewMode('gearViewMode')
  const [weightUnit, setWeightUnit] = useWeightUnit('gearWeightUnit')
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)


  // Filter items based on search and category with memoization
  const filteredItems = useMemo(() => {
    let filtered = items

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchLower) ||
        item.brand?.toLowerCase().includes(searchLower) ||
        item.model?.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower) ||
        item.notes?.toLowerCase().includes(searchLower) ||
        item.description?.toLowerCase().includes(searchLower)

import { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Plus } from 'lucide-react'
import { AppHeader } from '@/components/navigation/AppHeader'
import { CollectionHeader } from './CollectionHeader'

interface FilterOption {
  value: string
  label: string
  count?: number
}

interface EmptyStateConfig {
  icon: ReactNode
  title: string
  description: string
  noItemsTitle?: string
  noItemsDescription?: string
  showAddButton?: boolean
  addButtonText?: string
}

interface CollectionPageProps<TItem> {
  // Core data
  items: TItem[]
  filteredItems: TItem[]
  loading: boolean

  // Header configuration
  title: string
  backTo?: string

  // Search and filtering
  searchTerm: string
  onSearchChange: (term: string) => void
  searchPlaceholder?: string

  // Primary filter (optional)
  primaryFilter?: {
    options: FilterOption[]
    selectedValue: string | null
    onSelectValue: (value: string | null) => void
    placeholder?: string
    allItemsLabel?: string
    totalItems?: number
    mobileFilterOptions?: FilterOption[]
  }


  // View mode support (optional)
  viewMode?: {
    current: string
    onChange: (mode: string) => void
    component: ReactNode
  }

  // Secondary controls (optional)
  secondaryControls?: ReactNode


  // Empty states
  emptyState: EmptyStateConfig

  // Item rendering
  renderItems: (items: TItem[], viewMode?: string) => ReactNode

  // Action handlers
  onAdd?: () => void

  // Modal slots
  renderModals?: () => ReactNode

  // Floating action button
  showFloatingActionButton?: boolean

  // Custom loading skeleton
  renderLoadingSkeleton?: () => ReactNode
}

export function CollectionPage<TItem>({
  items,
  filteredItems,
  loading,
  title,
  backTo,
  searchTerm,
  onSearchChange,
  searchPlaceholder,
  primaryFilter,
  viewMode,
  secondaryControls,
  emptyState,
  renderItems,
  onAdd,
  renderModals,
  showFloatingActionButton = false,
  renderLoadingSkeleton
}: CollectionPageProps<TItem>) {

import { Button } from '@/components/ui/button'
import { User, LogOut, Mountain, Package, MapPin } from 'lucide-react'
import { Link, useLocation } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'

interface AppHeaderProps {
  title?: string
  subtitle?: string
  icon?: React.ReactNode
  backTo?: string
  isDashboard?: boolean
  rightContent?: React.ReactNode
}

