                  <LogOut className="h-4 w-4 sm:mr-2" />
                  <span className="hidden sm:inline">Sign out</span>
                </Button>
              </div>
            )}
          </div>
        </div>
      </nav>
    </header>
  )
}

import React, { ReactNode, useState, useEffect } from 'react'
import { NavLink, useLocation } from 'react-router-dom'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { UserDropdownMenu } from './UserDropdownMenu'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { Mountain, Home, ListTodo, Package, User, ChevronUp, ChevronDown, PanelLeft } from 'lucide-react'
import { useAuth } from '@/contexts/AuthContext'
import { useSidebar } from '@/contexts/SidebarContext'
import { getDisplayNameFromEmail } from '@/utils/user'

interface AppLayoutProps {
  children: ReactNode
}

interface NavItem {
  label: string
  href: string
  icon: React.ComponentType<{ className?: string }>
  mobileOnly?: boolean
  desktopOnly?: boolean
}

const navItems: NavItem[] = [
  { label: 'Home', href: '/', icon: Home },
  { label: 'Lists', href: '/lists', icon: ListTodo },
  { label: 'Gear', href: '/gear', icon: Package },
  { label: 'Profile', href: '/profile', icon: User },
]

export function AppLayout({ children }: AppLayoutProps) {
  const { user, signOut } = useAuth()
  const { isCollapsed: isSidebarCollapsed, toggleSidebar } = useSidebar()
  const location = useLocation()
  const [isMobile, setIsMobile] = useState(false)
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false)

  useEffect(() => {
    const checkMobile = () => {
      // Show mobile nav below lg breakpoint (1024px) to match sidebar visibility
      setIsMobile(window.innerWidth < 1024)
    }

    checkMobile()

    // Debounce resize events for better performance
    let resizeTimer: NodeJS.Timeout
    const handleResize = () => {
      clearTimeout(resizeTimer)
      resizeTimer = setTimeout(checkMobile, 150)
    }

    window.addEventListener('resize', handleResize)
    return () => {
      window.removeEventListener('resize', handleResize)
      clearTimeout(resizeTimer)
    }
  }, [])


  const isActiveRoute = (path: string) => {
    if (path === '/') {
      return location.pathname === '/' || location.pathname === '/dashboard'
    }
    return location.pathname === path || location.pathname.startsWith(path + '/')
  }

  return (
    <div className="min-h-screen bg-background">
      {/* Desktop Sidebar - Hidden on mobile */}
      <aside 
        role="complementary"
        aria-label="Main navigation"
        className={cn(
          "fixed left-0 top-0 z-40 h-screen bg-white border-r border-border/40 transition-all duration-200",
          "hidden lg:block",
          isSidebarCollapsed ? "w-20" : "w-64"
        )}>
        <div className="flex flex-col h-full">
          {/* Logo/Brand */}
          <div className="border-b border-border/40">
            <div className="flex items-center justify-between px-6 py-5">
              <div className={cn(
                "flex items-center",
                isSidebarCollapsed ? "justify-center w-full" : "space-x-3"
              )}>
                <div className="p-2 bg-primary/10 rounded-lg">
                  <Mountain className="h-5 w-5 text-primary" />
                </div>
                {!isSidebarCollapsed && (
                  <span className="text-xl font-semibold">BetterPack</span>
                )}
              </div>
            </div>
          </div>

          {/* Navigation */}
          <nav className="flex-1 px-4 py-6 space-y-1" aria-label="Primary navigation">
            {navItems.filter(item => !item.mobileOnly).map((item) => {
              const Icon = item.icon
              const isActive = isActiveRoute(item.href)

              if (isSidebarCollapsed) {
                return (
                  <TooltipProvider key={item.href}>
                    <Tooltip delayDuration={0}>
                      <TooltipTrigger asChild>
                        <NavLink
                          to={item.href}
                          className={cn(
                            "flex items-center justify-center px-3 py-2.5 rounded-lg transition-colors duration-150",
                            "hover:bg-accent",
                            isActive && "bg-primary/10 text-primary font-medium"
                          )}
                          aria-current={isActive ? "page" : undefined}
                        >
                          <Icon className="h-5 w-5" />
                        </NavLink>
                      </TooltipTrigger>
                      <TooltipContent side="right" className="font-medium text-sm">
                        <p>{item.label}</p>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                )
              }

              return (
                <NavLink
                  key={item.href}
                  to={item.href}
                  className={cn(
                    "flex items-center space-x-3 px-3 py-2.5 rounded-lg transition-colors duration-150",
                    "hover:bg-accent",
                    isActive && "bg-primary/10 text-primary font-medium"
                  )}
                  aria-current={isActive ? "page" : undefined}
                >
                  <Icon className="h-5 w-5" />
                  <span>{item.label}</span>
                </NavLink>
              )
            })}
          </nav>

          {/* User section with dropdown */}
          <div className="border-t border-border/40 p-3">
            {!isSidebarCollapsed ? (
              <DropdownMenu open={isUserMenuOpen} onOpenChange={setIsUserMenuOpen}>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="ghost"
                    className="w-full justify-between px-3 py-2.5 min-h-[44px] h-auto hover:bg-accent cursor-pointer"
                    aria-label="User menu"
                    aria-expanded={isUserMenuOpen}
                    aria-haspopup="true"
                  >
                    <div className="flex items-center space-x-3 min-w-0">
                      <div className="h-9 w-9 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
                        <User className="h-4 w-4 text-primary" />
                      </div>
                      <span className="text-sm font-medium truncate">
                        {user?.email ? getDisplayNameFromEmail(user?.email) : 'User'}
                      </span>
                    </div>
                    {/* Note: ChevronDown when open, ChevronUp when closed - matches collapsed state visual */}
                    {isUserMenuOpen ? (
                      <ChevronDown className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                    ) : (
                      <ChevronUp className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                    )}
                  </Button>
                </DropdownMenuTrigger>
                <UserDropdownMenu 
                  email={user?.email}
                  userName={user?.email ? getDisplayNameFromEmail(user?.email) : 'User'}
                  onSignOut={signOut}
                />
              </DropdownMenu>
            ) : (
              <DropdownMenu open={isUserMenuOpen} onOpenChange={setIsUserMenuOpen}>
                <TooltipProvider>
                  <Tooltip delayDuration={0}>
                    <TooltipTrigger asChild>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="sm"
                          className="w-full p-2 hover:bg-accent cursor-pointer"
                          aria-label="User menu"
                          aria-expanded={isUserMenuOpen}
                          aria-haspopup="true"
                        >
                          <User className="h-5 w-5" />
                        </Button>
                      </DropdownMenuTrigger>
                    </TooltipTrigger>
                    <TooltipContent side="right" className="font-medium text-sm">
                      <p>{user?.email ? getDisplayNameFromEmail(user?.email) : 'Account'}</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
                <UserDropdownMenu 
                  email={user?.email}
                  userName={user?.email ? getDisplayNameFromEmail(user?.email) : 'User'}
                  onSignOut={signOut}
                />
              </DropdownMenu>
            )}
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <div className={cn(
        "min-h-screen flex flex-col transition-all duration-200",
        !isMobile && (isSidebarCollapsed ? "lg:pl-20" : "lg:pl-64"),
        isMobile && "pb-16" // Add padding for bottom nav on mobile
      )}>
        {/* Mobile Header - Only on small screens */}
        <header className="lg:hidden bg-white border-b border-border/40 sticky top-0 z-30" role="banner">
          <div className="flex items-center justify-between px-4 h-14">
            <NavLink to="/" className="flex items-center space-x-3 hover:opacity-80 transition-opacity">
              <div className="p-1.5 bg-primary/10 rounded-lg">
                <Mountain className="h-4 w-4 text-primary" />
              </div>
              <span className="text-lg font-semibold">BetterPack</span>
            </NavLink>

            <div className="flex items-center space-x-2">
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-muted-foreground hover:bg-accent cursor-pointer"
                    aria-label="User menu"
                    aria-haspopup="true"
                  >
                    <User className="h-5 w-5" />
                  </Button>
                </DropdownMenuTrigger>
                <UserDropdownMenu 
                  email={user?.email}
                  userName={user?.email ? getDisplayNameFromEmail(user?.email) : 'User'}
                  onSignOut={signOut}
                />
              </DropdownMenu>
            </div>
          </div>
        </header>


        {/* Page Content */}
        <main className="flex-1">
          {React.Children.map(children, child => {
            if (React.isValidElement(child)) {
              return React.cloneElement(child as React.ReactElement<any>, {
                onToggleSidebar: toggleSidebar,
                isSidebarCollapsed: isSidebarCollapsed,
              })
            }
            return child
          })}
        </main>
      </div>

      {/* Mobile Bottom Navigation - Only on mobile */}
      {isMobile && (
        <nav className="fixed bottom-0 left-0 right-0 z-50 bg-white border-t border-border/40" aria-label="Mobile navigation">
          <div className="flex items-center justify-around h-16">
            {navItems.filter(item => !item.desktopOnly).map((item) => {
              const Icon = item.icon
              const isActive = isActiveRoute(item.href)

              return (
                <NavLink
                  key={item.href}
                  to={item.href}
                  className={cn(
                    "flex flex-col items-center justify-center flex-1 h-full py-2 transition-colors duration-150 tap-highlight-transparent",
                    "active:bg-accent",
                    isActive ? "text-primary bg-primary/5" : "text-muted-foreground"
                  )}
                  aria-current={isActive ? "page" : undefined}
                  aria-label={item.label}
                >
                  <Icon className={cn(
                    "h-5 w-5 mb-1",
                    isActive && "text-primary"
                  )} />
                  <span className={cn(
                    "text-xs",
                    isActive && "font-medium"
                  )}>
                    {item.label}
                  </span>
                </NavLink>
              )
            })}
          </div>
        </nav>
      )}
    </div>
  )
}

